#include "fstr/scene_model.hpp"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{if(argc!=8)throw std::invalid_argument("model-dir width height rgba8 parts-f32 roles-f32 person-f32");fstr::SceneModel model(argv[1]);fstr::AnalysisImage im;im.width=std::stoi(argv[2]);im.height=std::stoi(argv[3]);if(im.width<1||im.height<1||im.width>2048||im.height>2048)throw std::invalid_argument("Input size");const auto n=std::size_t(im.width)*std::size_t(im.height);im.rgba.resize(n*4);fstr::PersonParts parts;parts.width=im.width;parts.height=im.height;parts.probabilities.resize(n);auto read=[](const char*p,void*d,std::size_t n){std::ifstream f(p,std::ios::binary);f.read(static_cast<char*>(d),static_cast<std::streamsize>(n));if(!f||f.peek()!=EOF)throw std::runtime_error("Input byte size mismatch");};read(argv[4],im.rgba.data(),im.rgba.size());read(argv[5],parts.probabilities.data(),n*sizeof(parts.probabilities[0]));auto result=model.analyze(im,parts);auto write=[](const char*p,const void*d,std::size_t n){std::ofstream f(p,std::ios::binary);f.write(static_cast<const char*>(d),static_cast<std::streamsize>(n));if(!f)throw std::runtime_error("Output failed");};write(argv[6],result.weights.data(),n*sizeof(result.weights[0]));write(argv[7],result.person.data(),n*4);std::cout<<im.width<<'x'<<im.height<<" native scene inference complete\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
